class MindMapRepository(
    private val database: AppDatabase,
    private val aiService: TencentCloudAIService
) {

    // Local-First: 优先返回本地数据
    fun getAllMindMapsFlow() = database.mindMapDao().getAllMindMapsFlow()

    suspend fun getMindMapByTopicId(topicId: String): MindMapEntity? {
        return database.mindMapDao().getByTopicId(topicId)
    }

    suspend fun generateMindMap(topicId: String): MindMapEntity? {
        // 1. 优先返回本地已有的MindMap
        val existingMindMap = database.mindMapDao().getByTopicId(topicId)
        if (existingMindMap != null) {
            return existingMindMap
        }

        // 2. 异步调用AI服务生成MindMap
        val topic = database.topicDao().getTopicByIdSync(topicId)
        if (topic == null) {
            return null
        }

        val mindMapEntity = aiService.generateMindMap(topicId, topic.title)

        if (mindMapEntity != null) {
            database.mindMapDao().insert(mindMapEntity)
        }

        return mindMapEntity
    }

    suspend fun updateNodeProgress(nodeId: String, progress: Int) {
        database.mindMapDao().updateNodeProgress(nodeId, progress)
    }
}

class MessageRepository(
    private val messageDao: MessageDao,
    private val topicDao: TopicDao,
    private val aiService: TencentCloudAIService
) {

    fun getMessagesByTopicFlow(topicId: String): Flow<List<MessageEntity>> {
        return messageDao.getByTopicIdFlow(topicId)
    }

    suspend fun getMessagesByTopicId(topicId: String): List<MessageEntity> {
        return messageDao.getByTopicId(topicId)
    }

    suspend fun sendMessageAndGetReply(topicId: String, userContent: String): MessageEntity? {
        // 1. 保存用户消息到本地数据库
        val userMessage = MessageEntity(
            id = UUID.randomUUID().toString(),
            topicId = topicId,
            content = userContent,
            senderType = "USER",
            messageType = "TEXT",
            timestamp = System.currentTimeMillis()
        )
        messageDao.insert(userMessage)

        // 2. 获取对话历史（用于AI分析）
        val conversationHistory = messageDao.getByTopicId(topicId)

        // 3. 异步调用AI服务分析进度
        val progressAnalysis = aiService.analyzeLearningProgress(conversationHistory)

        // 4. 构建上下文并获取AI回复
        val context = buildContext(conversationHistory, progressAnalysis)
        val aiResponse = aiService.sendMessage(conversationHistory, context)

        // 5. 保存AI回复到本地数据库
        val aiMessage = MessageEntity(
            id = UUID.randomUUID().toString(),
            topicId = topicId,
            content = aiResponse,
            senderType = "AI",
            messageType = "TEXT",
            timestamp = System.currentTimeMillis()
        )
        messageDao.insert(aiMessage)

        return aiMessage
    }
}

class TencentCloudAIServiceImpl(
    private val context: Context,
    private val apiKey: String,
    private val secretId: String,
    private val testMode: Boolean = false
) : TencentCloudAIService {

    private val apiClient: TencentCloudClient by lazy {
        TencentCloudClient.Builder(context)
            .setApiKey(apiKey)
            .setSecretId(secretId)
            .setTimeout(30000)
            .build()
    }

    companion object {
        const val BASE_URL = "https://knowledge-engine.tencentcloudapi.com"
    }

    private suspend fun <T> withRetry(
        maxRetries: Int = 3,
        operation: suspend () -> T
    ): T {
        repeat(maxRetries) { attempt ->
            try {
                return operation()
            } catch (e: Exception) {
                if (attempt == maxRetries - 1) throw e
                delay(1000L * (attempt + 1))
            }
        }
        throw IllegalStateException("Unexpected retry logic failure")
    }

    override suspend fun sendMessage(messages: List<MessageEntity>, context: String): String {
        return if (testMode) {
            mockSendMessage()
        } else {
            withRetry {
                apiClient.callChatAPI(messages, context)
            }
        }
    }

    private fun mockSendMessage(): String {
        return "这是一个测试回复。真实API调用被禁用。"
    }

